#!/usr/bin/env python3
import json
import sys
from http.server import HTTPServer, BaseHTTPRequestHandler
import threading

class BookHandler(BaseHTTPRequestHandler):
    books = []  # in-memory list of books
    next_id = 1

    def do_POST(self):
        if self.path == "/books":
            self.handle_post_books()
        else:
            self.send_error(404)

    def do_GET(self):
        if self.path == "/books":
            self.handle_get_books()
        elif self.path.startswith("/books/"):
            path = self.path[8:]  # remove /books/
            self.handle_get_book(path)
        else:
            self.send_error(404)

    def do_PUT(self):
        if self.path == "/books":
            pass
        elif self.path.startswith("/books/"):
            path = self.path[8:]
            self.handle_put_book(path)
        else:
            self.send_error(404)

    def do_DELETE(self):
        if self.path == "/books":
            pass
        elif self.path.startswith("/books/"):
            path = self.path[8:]
            self.handle_delete_book(path)
        else:
            self.send_error(404)

    def send_error(self, code, message=None):
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({"error": message or ""}).encode())

    def handle_post_books(self):
        global next_id
        try:
            content_length = int(self.headers.get('Content-Length', 0))
            body = self.rfile.read(content_length).decode()
            data = json.loads(body)
        except Exception:
            self.send_error(400, "Invalid JSON")
            return

        # basic validation
        required = ['title', 'author', 'isbn']
        for field in required:
            if field not in data:
                self.send_error(400, f"Missing required field: {field}")
                return
        if not data['title'].strip():
            self.send_error(400, "title is empty")
        if not data['author'].strip():
            self.send_error(400, "author is empty")
        if not data['isbn'].strip():
            self.send_error(400, "isbn is empty")
        if 'synopsis' in data and not data['synopsis'].strip():
            data['synopsis'] = ''

        book = {
            'id': next_id,
            'title': data['title'],
            'author': data['author'],
            'isbn': data['isbn'],
            'synopsis': data.get('synopsis', '')
        }
        books = self.books
        books.append(book)
        next_id += 1
        self.send_response(201)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(book).encode())

    def handle_get_book(self, path):
        # path is like "1"
        try:
            book_id = int(path)
        except ValueError:
            self.send_error(404)
            return
        books = self.books
        book = next((b for b in books if b['id'] == book_id), None)
        if not book:
            self.send_error(404)
            return
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(book).encode())

    def handle_put_book(self, path):
        try:
            book_id = int(path)
        except ValueError:
            self.send_error(404)
            return
        books = self.books
        book = next((b for b in books if b['id'] == book_id), None)
        if not book:
            self.send_error(404)
            return
        try:
            content_length = int(self.headers.get('Content-Length', 0))
            body = self.rfile.read(content_length).decode()
            data = json.loads(body)
        except Exception:
            self.send_error(400, "Invalid JSON")
            return
        # validation similar to POST
        required = ['title', 'author', 'isbn']
        for field in required:
            if field not in data:
                self.send_error(400, f"Missing required field: {field}")
                return
        if not data['title'].strip():
            self.send_error(400, "title is empty")
        if not data['author'].strip():
            self.send_error(400, "author is empty")
        if not data['isbn'].strip():
            self.send_error(400, "isbn is empty")
        book['title'] = data['title']
        book['author'] = data['author']
        book['isbn'] = data['isbn']
        book['synopsis'] = data.get('synopsis', '')
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(book).encode())

    def handle_delete_book(self, path):
        try:
            book_id = int(path)
        except ValueError:
            self.send_error(404)
            return
        books = self.books
        book = next((b for b in books if b['id'] == book_id), None)
        if not book:
            self.send_error(404)
            return
        books[:] = [b for b in books if b['id'] != book_id]
        self.send_response(204)
        self.end_headers()

def run_server(port):
    server = HTTPServer(('127.0.0.1', port), BookHandler)
    server.serve_forever()

if __name__ == "__main__":
    port = int(os.environ.get('PORT', 8000))
    run_server(port)
